        vm.assume(actor != address(0));
        vm.deal(actor, value);

        bool ok;
        vm.prank(actor, actor);
        try c.wager{value: value}() { ok = true; } catch { ok = false; }

        uint256 recorded = c.hasPlayerWagered(actor) ? value : 0; // placeholder; read actual below
        if (ok) {
            uint256 expected = value == c.currentBetLimit() ? value : 0;
            assertTrue(c.hasPlayerWagered(actor) && expected == value, "wager recorded inconsistent with betLimit");
